evidence.en:
const total = (accs) => accs.reduce((s, a) => s + a.cents, 0);

// split account a into b and c, half each
const before = total([a]);        // 1_000_001 cents (odd)

const half = a.cents / 2;         // 500000.5
b.cents = Math.round(half);       // 500001
c.cents = Math.round(half);       // 500001
a.cents = 0;

console.assert(total([a, b, c]) === before);
// FIRES: 1_000_002 !== 1_000_001

evidence.ru:
const total = (accs) => accs.reduce((s, a) => s + a.cents, 0);

// разделить счёт a на b и c, пополам
const before = total([a]);        // 1_000_001 центов (нечётно)

const half = a.cents / 2;         // 500000.5
b.cents = Math.round(half);       // 500001
c.cents = Math.round(half);       // 500001
a.cents = 0;

console.assert(total([a, b, c]) === before);
// СРАБАТЫВАЕТ: 1_000_002 !== 1_000_001
